import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount, address receiver) public {
        // Bound amount to avoid arithmetic issues, but keep it wide
        amount = bound(amount, 0, address(c).balance + 100 ether);
        // Assume sender is not zero address (and receiver can be anything)
        vm.assume(sender != address(0));

        // Fund the contract with enough ether
        vm.deal(address(c), amount + 1 ether);

        // Record balance before
        uint256 balanceBefore = address(c).balance;

        // Try the call as the given sender
        vm.prank(sender);
        // Deploy a Reverter to use as receiver if we want to test adversarial receiver behavior.
        // However, the generic rule must hold for ANY receiver, and the fuzzer provides one.
        // But to test the adversarial case where receiver reverts, we need to route through a helper.
        // Since the rule must hold for ALL admissible inputs, and the bug only manifests when
        // a non-owner calls succeed where they shouldn't, we can simply check:
        // If the call succeeds (does not revert), then either sender is owner or amount == 0
        // OR the contract balance decreased exactly by amount.
        // But the invariant about balance change being only possible by owner is the key.

        // Wrap in try/catch to see if it succeeded
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }

        uint256 balanceAfter = address(c).balance;

        if (ok) {
            // If the call succeeded, balance must have decreased by amount,
            // AND either the sender is the owner or amount == 0 (no-op).
            // The bug allows non-owners to drain balance, so they would
            // decrease balance even when sender != owner and amount > 0.
            assertTrue(
                (balanceBefore - balanceAfter == amount) &&
                (sender == c.owner() || amount == 0)
            );
        } else {
            // If the call reverted, balance must remain unchanged
            assertTrue(balanceBefore == balanceAfter);
        }
    }
}

